import proj4 from 'proj4';
import { LV95, SWISS_BOUNDS, WGS84 } from './constants.js';

proj4.defs('EPSG:2056', LV95);

export function wgs84ToLv95(coordinate) {
  return proj4(WGS84, 'EPSG:2056', coordinate);
}

export function lv95ToWgs84(coordinate) {
  return proj4('EPSG:2056', WGS84, coordinate);
}

export function radians(value) {
  return (value * Math.PI) / 180;
}

export function degrees(value) {
  return (value * 180) / Math.PI;
}

export function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

export function distance2d(a, b) {
  return Math.hypot(b[0] - a[0], b[1] - a[1]);
}

export function haversineMeters(a, b) {
  const earthRadius = 6_371_000;
  const lat1 = radians(a[1]);
  const lat2 = radians(b[1]);
  const dLat = lat2 - lat1;
  const dLon = radians(b[0] - a[0]);
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLon / 2) ** 2;
  return earthRadius * 2 * Math.atan2(Math.sqrt(h), Math.sqrt(1 - h));
}

export function pointInPolygon(point, polygon) {
  if (!polygon || polygon.length < 3) return false;
  let inside = false;
  for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
    const xi = polygon[i][0];
    const yi = polygon[i][1];
    const xj = polygon[j][0];
    const yj = polygon[j][1];
    const intersects =
      yi > point[1] !== yj > point[1] &&
      point[0] < ((xj - xi) * (point[1] - yi)) / (yj - yi || Number.EPSILON) + xi;
    if (intersects) inside = !inside;
  }
  return inside;
}

export function isInsideSwissBounds([lon, lat]) {
  return (
    lon >= SWISS_BOUNDS.west &&
    lon <= SWISS_BOUNDS.east &&
    lat >= SWISS_BOUNDS.south &&
    lat <= SWISS_BOUNDS.north
  );
}

export function bboxOfCoordinates(coordinates) {
  const bbox = [Infinity, Infinity, -Infinity, -Infinity];
  for (const coordinate of coordinates) {
    bbox[0] = Math.min(bbox[0], coordinate[0]);
    bbox[1] = Math.min(bbox[1], coordinate[1]);
    bbox[2] = Math.max(bbox[2], coordinate[0]);
    bbox[3] = Math.max(bbox[3], coordinate[1]);
  }
  return bbox;
}

export function bboxesIntersect(a, b) {
  return a[0] <= b[2] && a[2] >= b[0] && a[1] <= b[3] && a[3] >= b[1];
}

export function lineDistanceMeters(coordinates) {
  let distance = 0;
  for (let index = 1; index < coordinates.length; index += 1) {
    distance += distance2d(coordinates[index - 1], coordinates[index]);
  }
  return distance;
}

export function formatDuration(minutes) {
  const rounded = Math.max(0, Math.round(minutes));
  const hours = Math.floor(rounded / 60);
  const rest = rounded % 60;
  if (!hours) return `${rest} min`;
  return rest ? `${hours} h ${rest} min` : `${hours} h`;
}

export function formatDistance(meters) {
  return `${(meters / 1000).toFixed(meters < 10_000 ? 1 : 0)} km`;
}
