import { bboxOfCoordinates, haversineMeters, pointInPolygon } from './geo.js';
import { ByteLruCache, fetchGraphTile, fetchGzipJson, loadManifest } from './data-client.js';
import { ROUTE_LIMITS } from './constants.js';
import { GraphStore, generateRandomRoute, hashSeed, mulberry32 } from './router-core.js';

let manifest = null;
let stops = [];
let activeJob = 0;
let controller = null;
let cacheVersion = null;
const mobileDevice =
  /Android|iPhone|iPad|Mobile/i.test(self.navigator?.userAgent || '') ||
  (self.navigator?.deviceMemory || 8) <= 4;
let tileCache = new ByteLruCache((mobileDevice ? 80 : 160) * 1024 * 1024);

function progress(jobId, phase, message, value = null) {
  if (jobId !== activeJob) return;
  self.postMessage({ type: 'progress', jobId, phase, message, value });
}

function eligibleStops(area) {
  if (!area || area.type === 'switzerland') return stops;
  if (area.type === 'point') {
    return stops.filter(
      (stop) => haversineMeters([stop.lon, stop.lat], area.coordinate) <= area.radiusKm * 1000,
    );
  }
  if (area.type === 'polygon') {
    return stops.filter((stop) => pointInPolygon([stop.lon, stop.lat], area.coordinates));
  }
  return [];
}

function cellsNear(startStop, radius) {
  const search = [
    startStop.snapX - radius,
    startStop.snapY - radius,
    startStop.snapX + radius,
    startStop.snapY + radius,
  ];
  return manifest.cells.filter((cell) => {
    const bbox = cell.bbox;
    return bbox[0] <= search[2] && bbox[2] >= search[0] && bbox[1] <= search[3] && bbox[3] >= search[1];
  });
}

function searchRadii(targetMinutes) {
  const initial = Math.min(60_000, Math.max(12_000, (targetMinutes / 60) * 6_000));
  const radii = [];
  for (let radius = initial; radius < 60_000; radius += 10_000) radii.push(radius);
  if (!radii.length || radii.at(-1) !== 60_000) radii.push(60_000);
  return radii;
}

function closureBboxes(closures) {
  return (closures || []).map((closure) => closure.bbox || bboxOfCoordinates(closure.coordinates));
}

function pointSegmentDistanceSquared(px, py, ax, ay, bx, by) {
  const dx = bx - ax;
  const dy = by - ay;
  const lengthSquared = dx * dx + dy * dy;
  const t = lengthSquared
    ? Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / lengthSquared))
    : 0;
  const x = ax + t * dx;
  const y = ay + t * dy;
  return (px - x) ** 2 + (py - y) ** 2;
}

function stopsNearRoute(route, maxDistance = 700, maxStops = 8) {
  const coordinates = route.coordinatesLv95;
  const bbox = [Infinity, Infinity, -Infinity, -Infinity];
  for (let index = 0; index < coordinates.length; index += 3) {
    bbox[0] = Math.min(bbox[0], coordinates[index]);
    bbox[1] = Math.min(bbox[1], coordinates[index + 1]);
    bbox[2] = Math.max(bbox[2], coordinates[index]);
    bbox[3] = Math.max(bbox[3], coordinates[index + 1]);
  }
  const maximumSquared = maxDistance ** 2;
  const endpointClearanceSquared = 350 ** 2;
  const minimumSpacingSquared = 450 ** 2;
  const startX = coordinates[0];
  const startY = coordinates[1];
  const endX = coordinates.at(-3);
  const endY = coordinates.at(-2);
  const candidates = stops
    .filter(
      (stop) =>
        stop.id !== route.startStop.id &&
        stop.id !== route.endStop.id &&
        (stop.x - startX) ** 2 + (stop.y - startY) ** 2 > endpointClearanceSquared &&
        (stop.x - endX) ** 2 + (stop.y - endY) ** 2 > endpointClearanceSquared &&
        stop.x >= bbox[0] - maxDistance &&
        stop.x <= bbox[2] + maxDistance &&
        stop.y >= bbox[1] - maxDistance &&
        stop.y <= bbox[3] + maxDistance,
    )
    .map((stop) => {
      let distanceSquared = Infinity;
      for (let index = 3; index < coordinates.length; index += 3) {
        distanceSquared = Math.min(
          distanceSquared,
          pointSegmentDistanceSquared(
            stop.x,
            stop.y,
            coordinates[index - 3],
            coordinates[index - 2],
            coordinates[index],
            coordinates[index + 1],
          ),
        );
      }
      return { stop, distanceSquared };
    })
    .filter((item) => item.distanceSquared <= maximumSquared)
    .sort((a, b) => a.distanceSquared - b.distanceSquared);
  const selected = [];
  for (const item of candidates) {
    if (
      selected.every(
        ({ stop }) =>
          (stop.x - item.stop.x) ** 2 + (stop.y - item.stop.y) ** 2 >= minimumSpacingSquared,
      )
    ) {
      selected.push(item);
    }
    if (selected.length >= maxStops) break;
  }
  return selected.map(({ stop }) => ({
      id: stop.id,
      name: stop.name,
      transport: stop.transport,
      lon: stop.lon,
      lat: stop.lat,
      elevation: stop.snapZ || 0,
    }));
}

async function configure(message) {
  const jobId = message.jobId || 0;
  controller?.abort();
  controller = new AbortController();
  const nextManifest = await loadManifest(message.manifestUrl || '/data/manifest.json', controller.signal);
  if (cacheVersion !== nextManifest.dataVersion) {
    tileCache.clear();
    cacheVersion = nextManifest.dataVersion;
  }
  manifest = nextManifest;
  const stopsUrl = new URL(manifest.stops.url, manifest.baseUrl);
  stopsUrl.searchParams.set('v', manifest.stops.sha256.slice(0, 16));
  stops = await fetchGzipJson(stopsUrl, controller.signal);
  self.postMessage({
    type: 'configured',
    jobId,
    dataVersion: manifest.dataVersion,
    generatedAt: manifest.generatedAt,
    mode: manifest.mode,
    stopCount: stops.length,
    cellCount: manifest.cells.length,
  });
}

async function loadCell(cell, signal) {
  const cacheKey = `${manifest.dataVersion}:${cell.id}`;
  let tile = tileCache.get(cacheKey);
  if (!tile) {
    const tileUrl = new URL(cell.url, manifest.baseUrl);
    tileUrl.searchParams.set('v', cell.sha256.slice(0, 16));
    tile = await fetchGraphTile(tileUrl, signal);
    tileCache.set(cacheKey, tile);
  }
  return tile;
}

async function generate(message) {
  const { jobId, request } = message;
  activeJob = jobId;
  controller?.abort();
  controller = new AbortController();
  const abort = () => jobId !== activeJob || controller.signal.aborted;
  if (!manifest) await configure({ type: 'configure', jobId, manifestUrl: '/data/manifest.json' });

  progress(jobId, 'selection', 'Geeignete Haltestellen werden gesucht …', 0.05);
  const candidates = eligibleStops(request.area);
  if (!candidates.length) {
    throw Object.assign(new Error('In diesem Gebiet gibt es keine angebundene Bus- oder Bahnhaltestelle.'), {
      code: 'NO_START_STOP',
      suggestion: 'Gebiet oder Radius vergrößern oder schweizweit suchen.',
    });
  }

  const seed = request.seed || `${Date.now()}-${Math.random()}`;
  const random = mulberry32(hashSeed(seed));
  const firstStartIndex = Math.floor(random() * candidates.length);
  const startOptions = [candidates[firstStartIndex]];
  if (candidates.length > 1) {
    const offset = 1 + Math.floor(random() * (candidates.length - 1));
    startOptions.push(candidates[(firstStartIndex + offset) % candidates.length]);
  }
  const radii = searchRadii(request.durationMinutes);
  let route = null;
  let attemptsUsed = 0;
  let routeLoadedCells = 0;
  const blockedAreas = closureBboxes(request.closures);
  for (let startIndex = 0; startIndex < startOptions.length && !route; startIndex += 1) {
    const startStop = startOptions[startIndex];
    const loadedTiles = new Map();
    const startsLeft = startOptions.length - startIndex;
    const startBudget = Math.floor((ROUTE_LIMITS.maxAttempts - attemptsUsed) / startsLeft);
    let startAttempts = 0;
    for (let ringIndex = 0; ringIndex < radii.length && !route; ringIndex += 1) {
      const selectedCells = cellsNear(startStop, radii[ringIndex]);
      const newCells = selectedCells.filter((cell) => !loadedTiles.has(cell.id));
      for (let index = 0; index < newCells.length; index += 1) {
        if (abort()) throw new Error('ABORTED');
        const cell = newCells[index];
        progress(
          jobId,
          'loading',
          `Wegenetz bis ${Math.round(radii[ringIndex] / 1000)} km wird geladen (${index + 1}/${newCells.length}) …`,
          0.1 + (ringIndex / radii.length) * 0.32,
        );
        loadedTiles.set(cell.id, await loadCell(cell, controller.signal));
      }

      const graph = new GraphStore();
      loadedTiles.forEach((tile) => graph.addTile(tile));
      graph.finalize({
        allowMountainTrails: request.allowMountainTrails,
        closureBboxes: blockedAreas,
      });
      if (graph.nodeIndex(startStop.nodeId) === undefined) continue;
      const loadedStops = stops.filter((stop) => graph.nodeIndex(stop.nodeId) !== undefined);
      const ringsLeft = radii.length - ringIndex;
      const remainingStartAttempts = startBudget - startAttempts;
      if (remainingStartAttempts <= 0) break;
      const ringBudget = Math.max(1, Math.floor(remainingStartAttempts / ringsLeft));
      progress(jobId, 'routing', 'Zufällige Routenvarianten werden verglichen …', 0.46);
      let ringAttempts = 0;
      route = generateRandomRoute({
        graph,
        startStop,
        stops: loadedStops,
        targetMinutes: request.durationMinutes,
        seed: `${seed}:start-${startIndex}:ring-${ringIndex}`,
        maxAttempts: ringBudget,
        abort,
        onAttempt(_attempt, routeType) {
          ringAttempts += 1;
          progress(
            jobId,
            'routing',
            `${routeType === 'loop' ? 'Rundtour' : 'Streckentour'}: Variante ${attemptsUsed + ringAttempts} wird geprüft …`,
            0.46 + Math.min(0.46, (attemptsUsed + ringAttempts) / ROUTE_LIMITS.maxAttempts),
          );
        },
      });
      attemptsUsed += ringAttempts;
      startAttempts += ringAttempts;
      if (route) routeLoadedCells = loadedTiles.size;
    }
  }
  if (!route) {
    throw Object.assign(new Error('Keine Route erfüllt Dauer, Wegklasse und Abwechslungsgrenze.'), {
      code: 'NO_ROUTE',
      suggestion: 'Dauer oder Radius vergrößern oder Bergwanderwege erlauben.',
    });
  }
  route.dataVersion = manifest.dataVersion;
  route.generatedAt = manifest.generatedAt;
  route.mode = manifest.mode;
  route.loadedGraphCells = routeLoadedCells;
  route.nearbyStops = stopsNearRoute(route);
  progress(jobId, 'done', 'Route gefunden.', 1);
  self.postMessage({ type: 'result', jobId, route });
}

self.addEventListener('message', async (event) => {
  const message = event.data;
  try {
    if (message.type === 'cancel') {
      activeJob += 1;
      controller?.abort();
      return;
    }
    if (message.type === 'configure') await configure(message);
    if (message.type === 'generate') await generate(message);
  } catch (error) {
    if (error?.name === 'AbortError' || error?.message === 'ABORTED') return;
    self.postMessage({
      type: 'error',
      jobId: message.jobId,
      code: error.code || 'ROUTING_ERROR',
      message: error.message || 'Unbekannter Routingfehler.',
      suggestion: error.suggestion || 'Bitte eine neue Variante versuchen.',
    });
  }
});
