import { ungzip } from 'pako';
import { decodeGraphTile } from './graph-format.js';

async function decompressGzip(buffer) {
  if ('DecompressionStream' in globalThis) {
    const stream = new Blob([buffer]).stream().pipeThrough(new DecompressionStream('gzip'));
    return new Response(stream).arrayBuffer();
  }
  const output = ungzip(new Uint8Array(buffer));
  return output.buffer.slice(output.byteOffset, output.byteOffset + output.byteLength);
}

export async function fetchGzip(url, signal) {
  const response = await fetch(url, { signal, cache: 'force-cache' });
  if (!response.ok) throw new Error(`Datendatei konnte nicht geladen werden (${response.status}).`);
  const buffer = await response.arrayBuffer();
  // Vite and many CDNs transparently decode .gz responses when they send a
  // Content-Encoding header. Object storage often serves the same file as raw bytes.
  // Supporting both keeps the static deployment independent of server configuration.
  if (response.headers.get('content-encoding')?.includes('gzip')) return buffer;
  const signature = new Uint8Array(buffer, 0, Math.min(2, buffer.byteLength));
  if (signature[0] !== 0x1f || signature[1] !== 0x8b) return buffer;
  return decompressGzip(buffer);
}

export async function fetchGzipJson(url, signal) {
  const buffer = await fetchGzip(url, signal);
  return JSON.parse(new TextDecoder().decode(buffer));
}

export async function fetchGraphTile(url, signal) {
  const buffer = await fetchGzip(url, signal);
  const tile = decodeGraphTile(buffer);
  tile.byteLength = buffer.byteLength;
  return tile;
}

export class ByteLruCache {
  constructor(maxBytes) {
    this.maxBytes = maxBytes;
    this.bytes = 0;
    this.entries = new Map();
  }

  get(key) {
    const entry = this.entries.get(key);
    if (!entry) return undefined;
    this.entries.delete(key);
    this.entries.set(key, entry);
    return entry.value;
  }

  set(key, value, bytes = value?.byteLength || 0) {
    const existing = this.entries.get(key);
    if (existing) {
      this.bytes -= existing.bytes;
      this.entries.delete(key);
    }
    this.entries.set(key, { value, bytes });
    this.bytes += bytes;
    while (this.bytes > this.maxBytes && this.entries.size > 1) {
      const oldestKey = this.entries.keys().next().value;
      const oldest = this.entries.get(oldestKey);
      this.entries.delete(oldestKey);
      this.bytes -= oldest.bytes;
    }
  }

  clear() {
    this.entries.clear();
    this.bytes = 0;
  }
}

export async function loadManifest(url = '/data/manifest.json', signal) {
  const response = await fetch(url, { signal, cache: 'no-cache' });
  if (!response.ok) throw new Error(`Graphmanifest fehlt (${response.status}).`);
  const manifest = await response.json();
  const base = new URL(url, globalThis.location?.href || 'http://localhost/');
  manifest.baseUrl = base;
  return manifest;
}
