import { bboxesIntersect, distance2d } from './geo.js';
import { decodeEdgeGeometry } from './graph-format.js';
import { ROUTE_LIMITS } from './constants.js';

export function hashSeed(value) {
  let hash = 2166136261;
  for (const character of String(value)) {
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

export function mulberry32(seed) {
  return function random() {
    let value = (seed += 0x6d2b79f5);
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4_294_967_296;
  };
}

function edgeNoise(edgeId, seed) {
  let value = (edgeId ^ seed) >>> 0;
  value = Math.imul(value ^ (value >>> 16), 0x7feb352d);
  value = Math.imul(value ^ (value >>> 15), 0x846ca68b);
  value ^= value >>> 16;
  return 0.88 + (value / 4_294_967_295) * 0.24;
}

class MinHeap {
  constructor() {
    this.items = [];
  }

  push(node, priority) {
    const item = { node, priority };
    this.items.push(item);
    let index = this.items.length - 1;
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (this.items[parent].priority <= priority) break;
      this.items[index] = this.items[parent];
      index = parent;
    }
    this.items[index] = item;
  }

  pop() {
    if (!this.items.length) return null;
    const root = this.items[0];
    const tail = this.items.pop();
    if (this.items.length && tail) {
      let index = 0;
      while (true) {
        const left = index * 2 + 1;
        const right = left + 1;
        if (left >= this.items.length) break;
        let child = left;
        if (right < this.items.length && this.items[right].priority < this.items[left].priority) {
          child = right;
        }
        if (this.items[child].priority >= tail.priority) break;
        this.items[index] = this.items[child];
        index = child;
      }
      this.items[index] = tail;
    }
    return root;
  }

  get size() {
    return this.items.length;
  }
}

function geometryBbox(coordinates) {
  const bbox = [Infinity, Infinity, -Infinity, -Infinity];
  for (let index = 0; index < coordinates.length; index += 3) {
    bbox[0] = Math.min(bbox[0], coordinates[index]);
    bbox[1] = Math.min(bbox[1], coordinates[index + 1]);
    bbox[2] = Math.max(bbox[2], coordinates[index]);
    bbox[3] = Math.max(bbox[3], coordinates[index + 1]);
  }
  return bbox;
}

export class GraphStore {
  constructor() {
    this.nodeIndexById = new Map();
    this.nodeIds = [];
    this.nodeX = [];
    this.nodeY = [];
    this.nodeZ = [];
    this.edgesById = new Map();
    this.loadedCells = new Set();
    this.ready = false;
  }

  addTile(tile) {
    if (this.loadedCells.has(tile.header.cell)) return;
    const localNodes = new Uint32Array(tile.nodeIds.length);
    const [originX, originY] = tile.header.origin;

    for (let local = 0; local < tile.nodeIds.length; local += 1) {
      const id = tile.nodeIds[local];
      let index = this.nodeIndexById.get(id);
      if (index === undefined) {
        index = this.nodeIds.length;
        this.nodeIndexById.set(id, index);
        this.nodeIds.push(id);
        this.nodeX.push(originX + tile.nodeX[local] / 10);
        this.nodeY.push(originY + tile.nodeY[local] / 10);
        this.nodeZ.push(tile.nodeZ[local] / 10);
      }
      localNodes[local] = index;
    }

    for (let index = 0; index < tile.edgeIds.length; index += 1) {
      const id = tile.edgeIds[index];
      if (this.edgesById.has(id)) continue;
      const geometry = decodeEdgeGeometry(tile, index);
      this.edgesById.set(id, {
        id,
        from: localNodes[tile.edgeFrom[index]],
        to: localNodes[tile.edgeTo[index]],
        seconds: tile.edgeSeconds[index],
        distance: tile.edgeDistanceDm[index] / 10,
        ascent: tile.edgeAscentDm[index] / 10,
        descent: tile.edgeDescentDm[index] / 10,
        trailClass: tile.edgeClass[index],
        geometry,
        bbox: geometryBbox(geometry),
      });
    }
    this.loadedCells.add(tile.header.cell);
    this.ready = false;
  }

  finalize({ allowMountainTrails = false, closureBboxes = [] } = {}) {
    const edges = [...this.edgesById.values()].filter((edge) => {
      if (!allowMountainTrails && edge.trailClass > 0) return false;
      return !closureBboxes.some((bbox) => bboxesIntersect(edge.bbox, bbox));
    });
    const degrees = new Uint32Array(this.nodeIds.length);
    for (const edge of edges) {
      degrees[edge.from] += 1;
      degrees[edge.to] += 1;
    }
    this.offsets = new Uint32Array(this.nodeIds.length + 1);
    for (let index = 0; index < degrees.length; index += 1) {
      this.offsets[index + 1] = this.offsets[index] + degrees[index];
    }
    const arcCount = this.offsets[this.offsets.length - 1];
    this.targets = new Uint32Array(arcCount);
    this.arcEdge = new Uint32Array(arcCount);
    this.arcReverse = new Uint8Array(arcCount);
    this.arcSeconds = new Uint32Array(arcCount);
    const cursor = this.offsets.slice(0, -1);
    this.edges = edges;
    edges.forEach((edge, edgeIndex) => {
      let arc = cursor[edge.from]++;
      this.targets[arc] = edge.to;
      this.arcEdge[arc] = edgeIndex;
      this.arcSeconds[arc] = edge.seconds;
      arc = cursor[edge.to]++;
      this.targets[arc] = edge.from;
      this.arcEdge[arc] = edgeIndex;
      this.arcReverse[arc] = 1;
      this.arcSeconds[arc] = edge.seconds;
    });
    this.ready = true;
  }

  nodeIndex(globalId) {
    return this.nodeIndexById.get(globalId);
  }
}

function dijkstra(graph, start, options = {}) {
  const {
    maxCost = Infinity,
    target = null,
    seed = 0,
    penalizedEdges = null,
    abort = () => false,
  } = options;
  const distances = new Float64Array(graph.nodeIds.length);
  distances.fill(Infinity);
  const previousNode = new Int32Array(graph.nodeIds.length);
  previousNode.fill(-1);
  const previousArc = new Int32Array(graph.nodeIds.length);
  previousArc.fill(-1);
  const heap = new MinHeap();
  distances[start] = 0;
  heap.push(start, 0);
  let iterations = 0;

  while (heap.size) {
    const current = heap.pop();
    if (!current || current.priority !== distances[current.node]) continue;
    if (current.priority > maxCost) break;
    if (target !== null && current.node === target) break;
    if ((iterations++ & 2047) === 0 && abort()) throw new Error('ABORTED');

    for (let arc = graph.offsets[current.node]; arc < graph.offsets[current.node + 1]; arc += 1) {
      const edge = graph.edges[graph.arcEdge[arc]];
      const penalty = penalizedEdges?.has(edge.id) ? 7 : 1;
      const cost = graph.arcSeconds[arc] * edgeNoise(edge.id, seed) * penalty;
      const next = graph.targets[arc];
      const nextDistance = current.priority + cost;
      if (nextDistance < distances[next] && nextDistance <= maxCost) {
        distances[next] = nextDistance;
        previousNode[next] = current.node;
        previousArc[next] = arc;
        heap.push(next, nextDistance);
      }
    }
  }
  return { distances, previousNode, previousArc };
}

function reconstructPath(search, start, target) {
  if (!Number.isFinite(search.distances[target])) return null;
  const arcs = [];
  let node = target;
  while (node !== start) {
    const arc = search.previousArc[node];
    if (arc < 0) return null;
    arcs.push(arc);
    node = search.previousNode[node];
  }
  return arcs.reverse();
}

function routeStats(graph, arcs, startStop, endStop) {
  let distance = distance2d([startStop.x, startStop.y], [startStop.snapX, startStop.snapY]);
  let seconds = distance * 0.9;
  let ascent = 0;
  let descent = 0;
  let highestClass = 0;
  for (const arc of arcs) {
    const edge = graph.edges[graph.arcEdge[arc]];
    distance += edge.distance;
    seconds += edge.seconds;
    if (graph.arcReverse[arc]) {
      ascent += edge.descent;
      descent += edge.ascent;
    } else {
      ascent += edge.ascent;
      descent += edge.descent;
    }
    highestClass = Math.max(highestClass, edge.trailClass);
  }
  if (endStop.id !== startStop.id) {
    const connector = distance2d([endStop.x, endStop.y], [endStop.snapX, endStop.snapY]);
    distance += connector;
    seconds += connector * 0.9;
  }
  return {
    distanceMeters: distance,
    durationMinutes: seconds / 60,
    ascentMeters: ascent,
    descentMeters: descent,
    highestClass,
  };
}

function appendPoint(target, x, y, z) {
  const length = target.length;
  if (
    length >= 3 &&
    target[length - 3] === x &&
    target[length - 2] === y &&
    target[length - 1] === z
  ) {
    return;
  }
  target.push(x, y, z);
}

function routeGeometry(graph, arcs, startStop, endStop) {
  const result = [];
  appendPoint(result, startStop.x, startStop.y, startStop.elevation || 0);
  appendPoint(result, startStop.snapX, startStop.snapY, startStop.snapZ || 0);
  for (const arc of arcs) {
    const edge = graph.edges[graph.arcEdge[arc]];
    const geometry = edge.geometry;
    if (graph.arcReverse[arc]) {
      for (let index = geometry.length - 3; index >= 0; index -= 3) {
        appendPoint(result, geometry[index], geometry[index + 1], geometry[index + 2]);
      }
    } else {
      for (let index = 0; index < geometry.length; index += 3) {
        appendPoint(result, geometry[index], geometry[index + 1], geometry[index + 2]);
      }
    }
  }
  if (endStop.id !== startStop.id) {
    appendPoint(result, endStop.x, endStop.y, endStop.elevation || 0);
  } else {
    appendPoint(result, startStop.x, startStop.y, startStop.elevation || 0);
  }
  return result;
}

function repeatedEdgeRatio(graph, arcs) {
  const counts = new Map();
  let total = 0;
  let repeated = 0;
  for (const arc of arcs) {
    const edge = graph.edges[graph.arcEdge[arc]];
    total += edge.distance;
    const count = counts.get(edge.id) || 0;
    if (count) repeated += edge.distance;
    counts.set(edge.id, count + 1);
  }
  return total ? repeated / total : 1;
}

function toResult(graph, type, arcs, startStop, endStop, seed) {
  return {
    routeType: type,
    seed: String(seed),
    startStop,
    endStop,
    coordinatesLv95: routeGeometry(graph, arcs, startStop, endStop),
    stats: routeStats(graph, arcs, startStop, endStop),
    repeatedEdgeRatio: repeatedEdgeRatio(graph, arcs),
  };
}

function isWithinTolerance(duration, targetMinutes) {
  const delta = Math.abs(duration - targetMinutes) / targetMinutes;
  return delta <= ROUTE_LIMITS.tolerance;
}

function generatePointToPoint(graph, startStop, stops, targetMinutes, seed, abort) {
  const start = graph.nodeIndex(startStop.nodeId);
  if (start === undefined) return null;
  const search = dijkstra(graph, start, {
    maxCost: targetMinutes * 60 * 1.3,
    seed,
    abort,
  });
  const candidates = [];
  for (const stop of stops) {
    if (stop.id === startStop.id) continue;
    const node = graph.nodeIndex(stop.nodeId);
    if (node === undefined || !Number.isFinite(search.distances[node])) continue;
    if (search.distances[node] < targetMinutes * 60 * 0.72) continue;
    const arcs = reconstructPath(search, start, node);
    if (!arcs?.length) continue;
    const result = toResult(graph, 'point_to_point', arcs, startStop, stop, seed);
    if (isWithinTolerance(result.stats.durationMinutes, targetMinutes)) candidates.push(result);
  }
  if (!candidates.length) return null;
  const random = mulberry32(seed ^ 0xa3c59ac3);
  candidates.sort(
    (a, b) =>
      Math.abs(a.stats.durationMinutes - targetMinutes) -
        Math.abs(b.stats.durationMinutes - targetMinutes) ||
      random() - 0.5,
  );
  return candidates[Math.floor(random() * Math.min(5, candidates.length))];
}

function generateLoop(graph, startStop, targetMinutes, seed, abort) {
  const start = graph.nodeIndex(startStop.nodeId);
  if (start === undefined) return null;
  const outbound = dijkstra(graph, start, {
    maxCost: targetMinutes * 60 * 0.72,
    seed,
    abort,
  });
  const waypointCandidates = [];
  for (let node = 0; node < outbound.distances.length; node += 1) {
    const seconds = outbound.distances[node];
    if (
      Number.isFinite(seconds) &&
      seconds >= targetMinutes * 60 * 0.32 &&
      seconds <= targetMinutes * 60 * 0.62 &&
      graph.offsets[node + 1] - graph.offsets[node] >= 2
    ) {
      waypointCandidates.push(node);
    }
  }
  if (!waypointCandidates.length) return null;
  const random = mulberry32(seed ^ 0x91e10da5);
  const waypoint = waypointCandidates[Math.floor(random() * waypointCandidates.length)];
  const outArcs = reconstructPath(outbound, start, waypoint);
  if (!outArcs?.length) return null;
  const usedEdges = new Set(outArcs.map((arc) => graph.edges[graph.arcEdge[arc]].id));
  const inbound = dijkstra(graph, waypoint, {
    maxCost: targetMinutes * 60 * 0.9,
    target: start,
    seed: seed ^ 0x5bd1e995,
    penalizedEdges: usedEdges,
    abort,
  });
  const inArcs = reconstructPath(inbound, waypoint, start);
  if (!inArcs?.length) return null;
  const result = toResult(graph, 'loop', [...outArcs, ...inArcs], startStop, startStop, seed);
  if (result.repeatedEdgeRatio > ROUTE_LIMITS.maxRepeatedRatio) return null;
  return isWithinTolerance(result.stats.durationMinutes, targetMinutes) ? result : null;
}

export function generateRandomRoute({
  graph,
  startStop,
  stops,
  targetMinutes,
  seed,
  abort = () => false,
  onAttempt = () => {},
  maxAttempts = ROUTE_LIMITS.maxAttempts,
}) {
  const baseSeed = hashSeed(seed);
  const random = mulberry32(baseSeed);
  const firstType = random() < 0.5 ? 'loop' : 'point_to_point';
  const types = [firstType, firstType === 'loop' ? 'point_to_point' : 'loop'];
  const firstTypeAttempts = Math.ceil(maxAttempts * 0.65);
  const attemptsByType = [firstTypeAttempts, Math.max(0, maxAttempts - firstTypeAttempts)];
  let closest = null;
  let totalAttempts = 0;

  for (let typeIndex = 0; typeIndex < types.length; typeIndex += 1) {
    const type = types[typeIndex];
    for (let attempt = 0; attempt < attemptsByType[typeIndex]; attempt += 1) {
      if (abort()) throw new Error('ABORTED');
      totalAttempts += 1;
      onAttempt(totalAttempts, type);
      const attemptSeed = (baseSeed + Math.imul(totalAttempts, 0x9e3779b1)) >>> 0;
      const result =
        type === 'loop'
          ? generateLoop(graph, startStop, targetMinutes, attemptSeed, abort)
          : generatePointToPoint(graph, startStop, stops, targetMinutes, attemptSeed, abort);
      if (!result) continue;
      const score = Math.abs(result.stats.durationMinutes - targetMinutes);
      if (!closest || score < closest.score) closest = { result, score };
      if (score <= targetMinutes * 0.08) return result;
    }
    if (closest) return closest.result;
  }
  return null;
}
