const MAGIC = 'RHG1';
const VERSION = 1;
const HEADER_BYTES = 12;

function align4(value) {
  return (value + 3) & ~3;
}

function typedView(Type, buffer, offset, length) {
  const aligned = align4(offset);
  return {
    value: new Type(buffer, aligned, length),
    offset: aligned + Type.BYTES_PER_ELEMENT * length,
  };
}

export function decodeGraphTile(buffer) {
  const data = buffer instanceof ArrayBuffer ? buffer : buffer.buffer;
  const bytes = new Uint8Array(data);
  const magic = new TextDecoder().decode(bytes.subarray(0, 4));
  if (magic !== MAGIC) throw new Error(`Unbekanntes Graphformat: ${magic}`);

  const view = new DataView(data);
  const version = view.getUint16(4, true);
  if (version !== VERSION) throw new Error(`Nicht unterstützte Graphversion: ${version}`);

  const headerLength = view.getUint32(8, true);
  const header = JSON.parse(
    new TextDecoder().decode(bytes.subarray(HEADER_BYTES, HEADER_BYTES + headerLength)),
  );
  const { nodes, edges, geometryPoints } = header;
  let offset = align4(HEADER_BYTES + headerLength);
  let read;

  read = typedView(Uint32Array, data, offset, nodes);
  const nodeIds = read.value;
  offset = read.offset;
  read = typedView(Int32Array, data, offset, nodes);
  const nodeX = read.value;
  offset = read.offset;
  read = typedView(Int32Array, data, offset, nodes);
  const nodeY = read.value;
  offset = read.offset;
  read = typedView(Uint16Array, data, offset, nodes);
  const nodeZ = read.value;
  offset = read.offset;
  read = typedView(Uint32Array, data, offset, edges);
  const edgeIds = read.value;
  offset = read.offset;
  read = typedView(Uint32Array, data, offset, edges);
  const edgeFrom = read.value;
  offset = read.offset;
  read = typedView(Uint32Array, data, offset, edges);
  const edgeTo = read.value;
  offset = read.offset;
  read = typedView(Uint32Array, data, offset, edges);
  const edgeSeconds = read.value;
  offset = read.offset;
  read = typedView(Uint32Array, data, offset, edges);
  const edgeDistanceDm = read.value;
  offset = read.offset;
  read = typedView(Uint16Array, data, offset, edges);
  const edgeAscentDm = read.value;
  offset = read.offset;
  read = typedView(Uint16Array, data, offset, edges);
  const edgeDescentDm = read.value;
  offset = read.offset;
  read = typedView(Uint8Array, data, offset, edges);
  const edgeClass = read.value;
  offset = read.offset;
  read = typedView(Uint32Array, data, offset, edges + 1);
  const geometryOffsets = read.value;
  offset = read.offset;
  read = typedView(Int32Array, data, offset, geometryPoints);
  const geometryDx = read.value;
  offset = read.offset;
  read = typedView(Int32Array, data, offset, geometryPoints);
  const geometryDy = read.value;
  offset = read.offset;
  read = typedView(Uint16Array, data, offset, geometryPoints);
  const geometryZ = read.value;

  return {
    header,
    nodeIds,
    nodeX,
    nodeY,
    nodeZ,
    edgeIds,
    edgeFrom,
    edgeTo,
    edgeSeconds,
    edgeDistanceDm,
    edgeAscentDm,
    edgeDescentDm,
    edgeClass,
    geometryOffsets,
    geometryDx,
    geometryDy,
    geometryZ,
  };
}

function pushArray(target, array, Type) {
  const offset = align4(target.offset);
  new Type(target.buffer, offset, array.length).set(array);
  target.offset = offset + Type.BYTES_PER_ELEMENT * array.length;
}

export function encodeGraphTile(tile) {
  const encoder = new TextEncoder();
  const header = {
    cell: tile.cell,
    origin: tile.origin,
    bbox: tile.bbox,
    nodes: tile.nodeIds.length,
    edges: tile.edgeIds.length,
    geometryPoints: tile.geometryDx.length,
  };
  const headerData = encoder.encode(JSON.stringify(header));
  const arrays = [
    [tile.nodeIds, Uint32Array],
    [tile.nodeX, Int32Array],
    [tile.nodeY, Int32Array],
    [tile.nodeZ, Uint16Array],
    [tile.edgeIds, Uint32Array],
    [tile.edgeFrom, Uint32Array],
    [tile.edgeTo, Uint32Array],
    [tile.edgeSeconds, Uint32Array],
    [tile.edgeDistanceDm, Uint32Array],
    [tile.edgeAscentDm, Uint16Array],
    [tile.edgeDescentDm, Uint16Array],
    [tile.edgeClass, Uint8Array],
    [tile.geometryOffsets, Uint32Array],
    [tile.geometryDx, Int32Array],
    [tile.geometryDy, Int32Array],
    [tile.geometryZ, Uint16Array],
  ];
  let total = align4(HEADER_BYTES + headerData.length);
  for (const [array, Type] of arrays) total = align4(total) + array.length * Type.BYTES_PER_ELEMENT;

  const buffer = new ArrayBuffer(total);
  const bytes = new Uint8Array(buffer);
  bytes.set(encoder.encode(MAGIC), 0);
  const view = new DataView(buffer);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, 0, true);
  view.setUint32(8, headerData.length, true);
  bytes.set(headerData, HEADER_BYTES);

  const target = { buffer, offset: align4(HEADER_BYTES + headerData.length) };
  for (const [array, Type] of arrays) pushArray(target, array, Type);
  return buffer;
}

export function decodeEdgeGeometry(tile, edgeIndex) {
  const start = tile.geometryOffsets[edgeIndex];
  const end = tile.geometryOffsets[edgeIndex + 1];
  const coordinates = new Float64Array((end - start) * 3);
  const [originX, originY] = tile.header.origin;
  let x = 0;
  let y = 0;
  for (let source = start, target = 0; source < end; source += 1, target += 3) {
    if (source === start) {
      x = originX * 10 + tile.geometryDx[source];
      y = originY * 10 + tile.geometryDy[source];
    } else {
      x += tile.geometryDx[source];
      y += tile.geometryDy[source];
    }
    coordinates[target] = x / 10;
    coordinates[target + 1] = y / 10;
    coordinates[target + 2] = tile.geometryZ[source] / 10;
  }
  return coordinates;
}
